INSERT INTO `empresa_info` (`idEmpresa`, `nombre`, `eslogan`, `resumen`, `mision`, `vision`, `telefono`, `telefono_movil`, `whatsapp`, `correo`, `direccion`, `horario`, `logo`, `facebook`, `instagram`, `actualizado_en`) VALUES
(1, 'Concentrados El Gordito', 'Nutrición Animal de Alto Rendimiento para el Campo Salvadoreño', 'Somos una empresa salvadoreña dedicada a la elaboración y distribución de alimentos balanceados y concentrados de primera calidad para aves, ganado bovino y porcinos. Impulsamos la productividad agropecuaria con fórmulas de precisión e ingredientes rigurosamente seleccionados.', 'Proveer soluciones nutricionales balanceadas con los más altos estándares de calidad, materias primas de primera categoría y tecnología de molienda avanzada, maximizando el rendimiento, la salud y la rentabilidad de las granjas salvadoreñas.', 'Consolidarnos como la planta de concentrados líder y más confiable de El Salvador, reconocida por la excelencia de nuestras fórmulas, trazabilidad productiva y compromiso genuino con el desarrollo agropecuario.', '+503 2440-1234', '+503 7890-5678', +50378905678, 'contacto@concentradoselgordito.com', 'Carretera Panamericana Km 65, El Salvador', 'Lunes a Viernes: 7:00 AM – 5:00 PM | Sábados: 7:00 AM – 12:00 MD', 'views/Recursos/logo.png', 'https://facebook.com', 'https://instagram.com', '2026-09-06 05:58:39');
