INSERT INTO `plan_pago` (`idPlanPago`, `nombrePlan`, `descripcion`, `monto`, `duracion_dias`, `activo`, `creado_en`, `actualizado_en`) VALUES
(1, 'Plan Básico Granjero', 'Acceso al portal de pedidos 24/7; Despacho regular de concentrados; Historial de compras y facturación; Soporte técnico por correo y WhatsApp', 1.00, 30, 1, '2026-06-28 10:34:19', '2026-09-05 19:33:20'),
(2, 'Plan Premium Productores', 'Todo lo del Plan Básico; Descuentos del 8% por volumen programado; Asesoría nutricional y balanceo de dietas; Prioridad en cola de despacho; Soporte directo vía WhatsApp 24/7', 300.00, 30, 1, '2026-06-28 10:34:19', '2026-09-05 19:30:58'),
(3, 'Plan Enterprise Agroindustrial', 'Formulaciones y mezclas exclusivas a la medida; Entregas programadas a nivel nacional; Línea de crédito comercial preferencial; Gestor de cuenta y visitas técnicas en granja; Trazabilidad completa y control de laboratorio', 800.00, 30, 1, '2026-06-28 10:34:19', '2026-09-05 19:30:58'),
(10, 'Plan Trimestral Ahorro Avícola', 'Abastecimiento garantizado para ciclos de engorde y postura; Tarifa fija protegida durante 90 días; Entregas mensuales de fórmulas frescas; Asesoría técnica en conversión alimenticia', 420.00, 90, 0, '2026-06-28 14:50:54', '2026-09-05 19:32:57'),
(11, 'Plan Semestral Nutrición Porcina', 'Programa intensivo de inicio, crecimiento y engorde; Acompañamiento zootécnico semestral; Análisis bromatológico periódico de raciones; Despacho quincenal a granja; Descuento preferencial del 12%', 850.00, 180, 0, '2026-06-28 14:50:54', '2026-09-05 19:32:52'),
(12, 'Plan Anual Cooperativas y Asociados', 'Cobertura integral para múltiples centros de producción; Precios mayoristas de fábrica todo el año; Auditorías nutricionales y de rendimiento en campo; Financiamiento y crédito rotativo comercial; Gestor VIP asignado', 1600.00, 365, 0, '2026-06-28 14:50:54', '2026-09-05 19:32:34');
